@franz1981  I have do some test about autovectorisation. 
We can draw conclusions from the results.
When using the constant offset(0) to read and write arrays, vector optimization is indeed performed.
Before I modified, 'ByteBufUtil.writeAscii' did not perform vector optimization.
Win10 & jdk11.
```
Benchmark                                                    (offset)  (sourceSize)  (targetSize)  Mode  Cnt    Score   Error  Units
LogicalAggregationBenchmark.intersectionNoOffset                  N/A          1024           256  avgt    2   75.536          ns/op
LogicalAggregationBenchmark.intersectionWithConstantOffset0       N/A          1024           256  avgt    2   75.238          ns/op
LogicalAggregationBenchmark.intersectionWithOffset                  0          1024           256  avgt    2  184.604          ns/op
LogicalAggregationBenchmark.intersectionWithOffset                256          1024           256  avgt    2  139.983          ns/op
LogicalAggregationBenchmarkByteBuf.intersectionNoOffset           N/A          1024           256  avgt    2  248.856          ns/op
LogicalAggregationBenchmarkByteBuf.intersectionWithOffset           0          1024           256  avgt    2  251.659          ns/op
LogicalAggregationBenchmarkByteBuf.intersectionWithOffset         256          1024           256  avgt    2  247.303          ns/op
```

Test code below
```
public final class ByteBufUtilPerf {
    // Fast-Path implementation
    static int writeAscii(AbstractByteBuf buffer, int writerIndex, CharSequence seq, int srcIndex, int len) {

        // We can use the _set methods as these not need to do any index checks and reference checks.
        // This is possible as we called ensureWritable(...) before.
        for (int i = srcIndex, end = srcIndex + len; i < end; i++) {
            buffer._setByte(writerIndex++, AsciiString.c2b(seq.charAt(i)));
        }
        return len;
    }
}


//=============

@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Fork(1)
@State(Scope.Benchmark)
@Warmup(iterations = 2, time = 5)
@Measurement(iterations = 2, time = 5)
public class LogicalAggregationBenchmark {
    public static void main(String... args) throws RunnerException {
        Options opt = new OptionsBuilder()
                .include(LogicalAggregationBenchmark.class.getSimpleName())
                .build();

        new Runner(opt).run();
    }

    @Benchmark
    public void intersectionWithOffset(DynamicOffsetState state, Blackhole bh) {
        var target = state.target;
        var source = state.source;
        int offset = state.offset;
        for (int i = 0; i < state.target.length; ++i) {
            target[i] &= source[offset + i];
        }
        bh.consume(target);
    }

    @Benchmark
    public void intersectionNoOffset(BaseState state, Blackhole bh) {
        var target = state.target;
        var source = state.source;
        for (int i = 0; i < state.target.length; ++i) {
            target[i] &= source[i];
        }
        bh.consume(target);
    }

    @Benchmark
    public void intersectionWithConstantOffset0(BaseState state, Blackhole bh) {
        var target = state.target;
        var source = state.source;
        for (int i = 0; i < state.target.length; ++i) {
            target[i] &= source[ConstantOffset0State.offset + i];
        }
        bh.consume(target);
    }

    @State(Scope.Benchmark)
    public static class BaseState {
        @Param("256")
        int targetSize;

        @Param("1024")
        int sourceSize;

        long[] source;
        long[] target;

        private static void fill(long[] data) {
            for (int i = 0; i < data.length; ++i) {
                data[i] = ThreadLocalRandom.current().nextLong();
            }
        }

        @Setup(Level.Trial)
        public void setup() {
            source = new long[sourceSize];
            target = new long[targetSize];
            fill(source);
            fill(target);
        }
    }

    public static class ConstantOffset0State extends BaseState {
        private static final int offset = 0;
    }

    public static class DynamicOffsetState extends BaseState {
        @Param({ "0", "256" })
        int offset;
    }
}

