@State(Scope.Benchmark)
@Warmup(iterations = 2, time = 5)
@Measurement(iterations = 2, time = 5)
public class LogicalAggregationBenchmarkByteBuf {
    public static void main(String... args) throws RunnerException {
        Options opt = new OptionsBuilder()
                .include(LogicalAggregationBenchmarkByteBuf.class.getSimpleName())
                .build();

        new Runner(opt).run();
    }

    @Benchmark
    public void intersectionWithOffset(DynamicOffsetState state, Blackhole bh) {
        var target = state.target;
        var source = state.source;
        int offset = state.offset;
        ByteBufUtilPerf.writeAscii(target, 0, source, offset, target.capacity());
        bh.consume(target);
    }

    @Benchmark
    public void intersectionNoOffset(BaseState state, Blackhole bh) {
        var target = state.target;
        var source = state.source;
        ByteBufUtil.writeAscii(target, 0, source, target.capacity());
        bh.consume(target);
    }

    @State(Scope.Benchmark)
    public static class BaseState {
        @Param("256")
        int targetSize;

        @Param("1024")
        int sourceSize;

        CharSequence source;
        AbstractByteBuf target;

        private static void fill(byte[] data) {
            ThreadLocalRandom.current().nextBytes(data);
        }

        @Setup(Level.Trial)
        public void setup() {
            byte[] bytes = new byte[sourceSize];
            fill(bytes);

            source = new String(bytes, CharsetUtil.US_ASCII);
            target = (AbstractByteBuf) UnpooledByteBufAllocator.DEFAULT.heapBuffer(targetSize);
        }
    }


    public static class DynamicOffsetState extends BaseState {
        @Param({ "0", "256" })
        int offset;
    }
}

